"""Targeted additions to the existing eighteen-chapter monograph (no raw-data edits)."""
from pathlib import Path
import struct

def illustration(asset,name,alt):
 with (Path(__file__).resolve().parents[1]/'images'/f'{name}.png').open('rb') as image:
  header=image.read(24)
 width,height=struct.unpack('>II',header[16:24])
 return f'<figure id="illustration-{name}" class="editorial-illustration"><img src="{asset}/images/{name}.png" alt="{alt}" loading="lazy" width="{width}" height="{height}"></figure>'

def refine_chapters(sections,asset,eq,lab,player):
 def append(n,text):
  i=n-1;num,title,deck,body=sections[i];sections[i]=(num,title,deck,body+text)
 def replace(n,old,new):
  i=n-1;num,title,deck,body=sections[i];assert old in body,(n,old[:50]);sections[i]=(num,title,deck,body.replace(old,new))
 replace(1,'<p class="lead">','<div class="illustrated-intro">'+illustration(asset,'shopper-trolley','A shopper collecting a fixed list of household products')+'<p class="lead">')
 replace(1,'over time, how much more—or less—does that basket cost?</p>','over time, how much more—or less—does that basket cost?</p></div>')
 replace(4,'<div id="shock-illustration"></div>', '<div id="shock-illustration">'+illustration(asset,'digital-wallet','A digital wallet connecting expenditure amounts to basket shares')+'</div>')
 replace(3,'<div id="component-panels" class="component-grid"></div>', '<div id="component-panels" class="component-grid"></div><div class="illustrated-intro food-definition">'+illustration(asset,'food-service','A meal illustrating the grocery and restaurant purchases in the food component')+'<p><b>Food includes goods and services.</b> Grocery purchases and restaurant meals belong to the same major component. <span id="food-branch-summary"></span></p></div>')
 replace(3,'<h3>Open the classification</h3><div id="classification" class="classification"></div>', '''<h3>Open the classification</h3><p class="instruction">Select the + beside a category to explore its constituent groups. Each level opens or closes independently. The eight major components are visible from the start.</p><div id="classification" class="classification"></div><div id="classification-detail" class="classification-detail empirical-panel" aria-live="polite"></div>''')
 append(3,'''<h3>Containment, partitions and overlapping aggregates</h3><p>A product hierarchy nests narrower classes inside broader classes. A special aggregate instead selects a set of consumption items, often crossing several branches. In the diagrams, position shows membership; area does not represent an expenditure share.</p>'''+eq(r'A\subseteq B,\qquad A\cap B,\qquad A\cup B','A ⊆ B means every member of A is in B. A ∩ B contains their shared members; A ∪ B contains members of either set. These are sets of consumption items, not sets of numerical index values.')+lab('Explore the set before averaging its prices','''<div class="controls"><label>Relationship <select id="set-view"><option value="hierarchy">Published product hierarchy</option><option value="partition">Goods and services partition</option><option value="overlap">Overlapping special aggregates</option></select></label><label>Highlight <select id="set-selection"></select></label></div><div id="set-diagram" class="set-diagram"></div><div id="set-description" class="worked" aria-live="polite"></div>''','OFFICIAL CLASSIFICATION · SCHEMATIC SET GEOMETRY')+'''<p class="source">Definitions: CPI Reference Paper, Chapters 4 and 6; Table 18-10-0004-01 product codelist and release Table 1. Energy includes electricity, natural gas, fuel oil and other fuels, gasoline, and fuel/parts/accessories for recreational vehicles. Fuel is a good even when it appears in a shelter or recreation branch.</p>''')
 append(4,lab('Three products: fixed quantities, changing expenditure shares','''<p>The recurring miniature universe contains milk, a rental-service proxy and gasoline. Its reference expenditures are $20, $50 and $30. The same offers reappear in the elementary and upper-level walkthroughs.</p><label>Move from reference to later prices <input id="mini-price-progress" type="range" min="0" max="1" step="0.01" value="1"></label><div id="mini-weight-table" class="table-wrap"></div><div id="mini-weight-chart" class="chart"></div><div id="mini-weight-result" class="worked" aria-live="polite"></div>''')+'''<p>Holding quantities fixed does not hold their dollar shares fixed: expensive branches take a larger share after repricing. To aggregate relatives measured from the original price reference, use the corresponding original hybrid shares. To aggregate a subsequent interval, update the shares to its starting prices. Arbitrary current household budgets do not supply those shares.</p>''')
 append(5,'''<h3>Sample a population of transactions, not an abstract list of prices</h3><div class="illustrated-intro">'''+illustration(asset,'shopper-market','A shopper selecting representative products from a market shelf')+'''<p>The conceptual population consists of in-scope consumption by private households, expressed through transactions involving products, sellers, places and conditions. A collected product offer is an observed representative of part of that population. Observing every transaction is infeasible; a frame, a selection procedure and a rule for maintaining comparability connect the population to the sample.</p></div><div class="sampling-panel"><h4>Three stages in the general collection strategy</h4><p>Census subdivisions and collection areas organize geographical selection; outlet frames connect locations to product classes; representative-product specifications guide the selection of actual offers. This general framework has important exceptions.</p>'''+player('sampling-player','Geography, outlets and product-offer selection')+'''<div class="three sampling-notes"><div><h4>1 · Geography</h4><p>Collection areas are based on census subdivisions, with larger subdivisions split into smaller areas. Population and economic activity inform selection. A collection area is not automatically a separately published CPI geography.</p></div><div><h4>2 · Outlets</h4><p>The Business Register, retail commodity and service surveys link sellers to product classes. Pre-contact checks validate eligibility; subsequent outlet selection and replacement lists support ongoing collection. Revenue information helps represent the markets in which consumers buy.</p></div><div><h4>3 · Products</h4><p>Experts specify representative products. Assigning one to an outlet creates a target product offer; collection selects a locally relevant actual offer matching those specifications. Allocation reflects expenditure weight, variability and collection cost.</p></div></div></div>
<h3>Choose the observations in a miniature sampling frame</h3><div class="sampling-intro"><p>Explore four artificial areas, three outlets in each area and five offers per outlet. Each of the 60 offers has two monthly prices. Choose an area, an outlet or individual offers; the geometric mean uses exactly the selected observations. This is an equal-offer teaching estimator, not the official CPI sample design or a valid expenditure-weighted estimator of Canadian inflation.</p></div>'''+lab('A visible 4 × 3 × 5 population','''<p class="sampling-instruction"><b>Select or deselect</b> individual product offers; results <b>update automatically</b>. Area and outlet filters limit which offers enter the calculation. Muted offers outside the filters retain their saved selection, but are excluded until the filters are cleared.</p><div class="controls"><label>Area <select id="sample-area"><option value="all">All four areas</option><option value="0">Area A</option><option value="1">Area B</option><option value="2">Area C</option><option value="3">Area D</option></select></label><label>Outlet <select id="sample-outlet"><option value="all">All outlets in scope</option><option value="0">Outlet 1</option><option value="1">Outlet 2</option><option value="2">Outlet 3</option></select></label><button type="button" id="sample-frame-reset">Restore all offers</button></div><p class="hint">Each tile shows a <b>price relative</b> (later price ÷ earlier price), not a dollar price. ✓ means included; ○ means deselected; — means outside the current filters.</p><div id="sample-frame-status" class="sample-frame-status" aria-live="polite"></div><div id="sample-frame" class="sample-frame"></div><div id="sample-frame-comparison" class="sample-comparison" aria-live="polite"></div><div id="sample-frame-result" class="worked" aria-live="polite"></div><details><summary>Inspect selected prices, relatives and logarithms</summary><div id="sample-frame-table" class="table-wrap"></div></details>''','SYNTHETIC POPULATION · USER-SELECTED SUBSET')+'''
<div class="two"><div class="sampling-panel"><h4>One design does not fit every product</h4><p>Scanner transactions supply specific-product unit prices; administrative records and online collection may replace field collection. Cut-off sampling ranks available outlets or products to cover much of a market. Profiles hold service bundles and consumer conditions fixed; bestseller methods address selected content markets. Full-universe cases, such as a single regulated fee, need no ordinary offer sample. Rent and owned accommodation use specialized methods.</p></div><div class="limitation-panel"><h4>What can go wrong between months?</h4><p>Missing sellers or products create coverage and selection effects. Replacements can alter quality or outlet mix; matching, explicit adjustments and imputation are then essential. An observed change may include measurement error as well as price movement. Neither a large sample nor a geometric mean resolves a systematically unrepresentative frame.</p></div></div><p>The sampling simulation in Chapter 17 isolates variation under an explicitly specified synthetic design. It does not provide a confidence interval for official CPI.</p><p class="source">Source: <a href="https://www150.statcan.gc.ca/n1/pub/62-553-x/2023001/chap-5-eng.htm">Statistics Canada, Reference Paper, Chapter 5</a>, especially 5.4–5.14 and 5.22–5.31; Chapter 9. Procedures are described at the documented reference-paper vintage; no claim is made that every current offer follows the same probability design.</p>
<h3>Product replacement: observe a difference, then assess its meaning</h3>'''+lab('A laptop with improved characteristics','''<div class="product-comparison"><div><span class="eyebrow">EARLIER MODEL</span><div class="laptop-icon" aria-hidden="true">▱</div><strong>$900</strong><p>Specified memory, processor and storage.</p></div><div><span class="eyebrow">REPLACEMENT MODEL</span><div class="laptop-icon" aria-hidden="true">▱</div><strong>$1,000</strong><p>Improved characteristics; assumed quality value below.</p></div></div><label>Assumed dollar value of the quality improvement <input type="range" id="quality-value" min="0" max="150" step="5" value="80"></label><div id="quality-result" class="worked" aria-live="polite"></div>''')+'''<p>The assumed adjustment is not an estimated hedonic coefficient. If an appropriate comparable replacement or quality estimate cannot be established, other documented replacement or imputation methods are needed. A change in what households choose to buy is also distinct from an adjustment for quality in a matched price comparison.</p>''')
 append(6,'''<h3>When information supports explicit elementary weights</h3>'''+eq(r'G_w=\prod_i r_i^{\alpha_i}=\exp\left(\sum_i\alpha_i\log r_i\right),\qquad \alpha_i\ge0,\quad\sum_i\alpha_i=1','αᵢ is an explicit elementary weight. Taking logs changes the product into a weighted sum. Equal αᵢ = 1/n recovers Jevons. These weights belong inside the elementary calculation and are not automatically the eight major-component basket shares.')+lab('A price relative moves; the geometric mean follows','''<p>The two milk offers are the same ones used in the continuous miniature CPI walkthrough.</p><div class="controls"><label>Second milk offer, later price <input id="weighted-milk-price" type="range" min="3" max="8" step="0.05" value="5.25"></label><label>First offer’s explicit weight, % <input id="elementary-weight" type="range" min="0" max="100" step="1" value="60"></label></div><div id="relative-distribution" class="chart"></div><div id="weighted-elementary-result" class="worked" aria-live="polite"></div>''')+'''<p>The Reference Paper documents an explicitly weighted geometric formula in a few cases with more detailed information below the elementary level, including postal fees and selected newspaper, magazine and transport classes. Its paragraph 6.19 emphasizes that the weights need not have the same reference period as the price comparison. Which products, weights and linking conventions are appropriate is part of the method; this teaching control does not reproduce a particular exceptional official series.</p><p class="source">Source: <a href="https://www150.statcan.gc.ca/n1/pub/62-553-x/2023001/chap-6-eng.htm">Reference Paper, Chapter 6</a>, 6.18–6.19, equation (6.4), and Appendix A.</p>''')
 append(8,'''<h3>One miniature universe, from offers to a monthly rate</h3><p>Follow the same milk, rental-service and gasoline offers introduced in Chapters 4 and 6. The rent values here are synthetic service proxies; official rent estimation has a separate methodology. This walkthrough starts with observed offers, then changes mathematical level explicitly.</p>'''+lab('Select a branch and expose its calculation','''<label>Trace <select id="continuous-branch"><option value="0">Milk → food proxy</option><option value="1">Rental-service → shelter proxy</option><option value="2">Gasoline → transportation proxy</option></select></label><div id="continuous-flow" class="continuous-flow"></div><div id="continuous-inputs" class="table-wrap"></div><div id="continuous-trace" class="worked" aria-live="polite"></div>''')+'''<p>The lower-level factors are geometric means of matched offers. The upper-level factor is an arithmetic expenditure-weighted mean of those factors. Multiplying an illustrative earlier index by that factor creates a later index; taking their ratio gives monthly inflation. Official series enter only in the separate empirical audit, where the full retail-price construction remains unavailable.</p>''')
 replace(8,'The miniature model has two food elementary groups and one shelter proxy.', 'The miniature model uses the same milk, rental-service and gasoline offers as Chapters 4 and 6.')
 replace(8,'Milk with half the food branch and food with 60% of the miniature basket has an effective 30% share at the common reference prices. Its contribution to the aggregate change is 0.30 × its elementary percentage change.', 'Here milk represents the food proxy and receives a 20% effective share at the common reference prices. Its contribution to the aggregate change is 0.20 × its elementary percentage change.')
 append(9,'''<p class="cross-reference">In the recurring miniature universe, price updating changes each reference share by its branch factor and renormalizes the total. Return to the <a href="#mini-weight-table">three-product table</a> to see original shares, later dollar expenditures and price-updated shares together. The chain example above then shows why a new basket must be connected at a common link rather than spliced by its dollar cost.</p>''')
 append(14,'''<h3>Compare the provinces on one scale</h3><p>The ranking includes the ten provinces only. The three northern capital-city observations have their own comparison below. Both use the same rate calculation from September 2025 and September 2026 indices.</p><div class="geo-legend"><span>Lower annual inflation</span><div></div><span>Higher annual inflation</span><small>Continuous scale: 0% to 7% YoY. Colour depicts a rate, not the regional price level.</small></div><div id="province-ranking" class="chart"></div><div id="territorial-ranking" class="chart"></div><details><summary>Verify every September geographical rate and source flag</summary><div id="geo-verification" class="table-wrap"></div></details>
<h3>Compare two to four historical trajectories</h3><div class="geographic-intro"><p>Select up to four published geographies. Every curve is calculated within its own series. A higher curve indicates faster annual price growth, not a higher absolute cost of living. The component comparison below uses matching product definitions and months.</p></div><fieldset id="geo-multi" class="geo-multi"><legend>Historical series · select 2–4</legend></fieldset><p id="geo-multi-status" class="hint" aria-live="polite"></p><div class="controls"><label>History begins <select id="geo-history-start"><option>2002</option><option>2010</option><option selected>2019</option><option>2024</option></select></label></div><div id="geo-comparison-chart" class="chart"></div><p id="geo-comparison-detail" class="chart-detail" aria-live="polite"></p><details><summary>Read the historical comparison as a table</summary><div id="geo-comparison-table" class="table-wrap"></div></details>
<h3>The same categories, different regional changes</h3>'''+'<div class="illustrated-intro regional-context">'+illustration(asset,'residential-neighbourhood','Residential buildings illustrating regional shelter price comparisons')+'<p>Food, shelter and transportation can have different price trajectories and different expenditure shares across regions. The chart compares component growth rates. It does not infer their percentage-point contribution from a national share.</p></div>'+'''<div class="controls"><label>First geography <select id="component-geo-a"></select></label><label>Second geography <select id="component-geo-b"></select></label></div><div id="regional-components-chart" class="chart"></div><div id="regional-components-table" class="table-wrap"></div>
<h3>How geographical aggregation works in a fixed-basket model</h3>'''+eq(r'P_g^{0,t}=\sum_i s_{i|g}^0r_{ig}^{0,t},\qquad P_{Canada}^{0,t}=\sum_g W_g^0P_g^{0,t}','g identifies a region and i a product group. sᵢ|g is the within-region reference expenditure share; Wg is the region’s share of the same nationwide reference expenditure. Both sets sum to one. This identity assumes a common fixed basket, compatible reference prices, consistent scope and additive detailed expenditures.')+lab('Three synthetic regions, three products','''<p>Each region prices food, shelter and transport at within-region shares 20%, 50% and 30%. Change a regional share or its transportation price change. Other regional shares renormalize proportionately; after an all-weight-in-one-region endpoint, reopening the other regions splits their weight equally.</p><div class="controls"><label>Region <select id="region-model-select"><option value="0">Region A</option><option value="1">Region B</option><option value="2">Region C</option></select></label><label>National expenditure share, % <input id="region-model-weight" type="range" min="0" max="100" step="0.01" value="40"></label><label>Transportation change, % <input id="region-model-shock" type="range" min="-10" max="30" step="0.5" value="8"></label></div><div id="region-model-table" class="table-wrap"></div><div id="region-model-result" class="worked" aria-live="polite"></div>''')+'''<div class="limitation-panel"><h4>Why published provincial levels cannot simply be averaged</h4><p>The real national index uses detailed geographic/product weights and basket linking. Published regional levels are separately linked and may have different index references. Averaging ten displayed levels does not recreate those operations. The synthetic identity above shows the economic weighting logic under explicit common-reference assumptions; it is not a reconstruction of the official national series.</p></div><p>Geographic coverage describes the population represented. It does not mean each municipality receives a CPI estimate or that prices are collected in every locality. Collection areas, geographic strata and published geographies serve related but different purposes; Chapter 5 explains their connection.</p><p class="source">Sources: <a href="https://www150.statcan.gc.ca/n1/daily-quotidien/261019/t002a-eng.htm">September 2026 geographical release table</a>; local Table 18-10-0004-01 SDMX, release PDF Table 2; Reference Paper Chapters 4–6. All displayed rate calculations preserve original source vectors and available flags.</p>''')
 append(4,'''<h3>Whose spending determines a basket share?</h3><p>The weights represent aggregate in-scope household expenditure. A household spending twice as much contributes twice as much to those expenditure totals; the method does not first give every household an equal vote. The Reference Paper calls this <em>plutocratic weighting</em>. Household Final Consumption Expenditure estimates support higher-level totals, while the Survey of Household Spending and supplementary sources supply detail. Neither the geometric mean of observed offers nor an average household budget is a substitute for that expenditure system.</p><p class="source">Reference Paper, Chapter 8, paragraphs 8.1–8.8; the 2026 basket documentation describes the expenditure vintage used here.</p>''')
 append(11,'''<h3>A seasonal product is a collection problem before it is an adjustment problem</h3><p>A winter jacket can disappear from a particular outlet in summer. That does not imply a zero price, and removing its expenditure weight every summer would change the basket as well as its prices. The Reference Paper describes calendar-year fixed-basket weights and out-of-season imputation for highly seasonal products. Donor movements from a broader aggregate maintain the calculation until comparable in-season observations return.</p>'''+eq(r'I_t^{missing}=I_{t-1}^{missing}\frac{I_t^{donor}}{I_{t-1}^{donor}}','A schematic donor-relative imputation. It assumes the missing branch follows the selected donor’s movement during the gap; actual donor selection and re-entry treatment depend on the product method.')+'''<p class="worked"><b>Synthetic example:</b> a missing branch last stood at 100.0. If its assumed donor moves from 150.0 to 153.0, the imputed branch becomes 100 × (153 / 150) = <b>102.0</b>. This fills a missing movement under an assumption; it does not observe an unavailable jacket’s price. Seasonal adjustment is a separate operation on an index history after collection and construction.</p><p class="source">Reference Paper, Chapter 10, paragraphs 10.29–10.40, especially 10.36–10.38. This explanation follows the documented 2023 method rather than asserting an independently verified 2026 operational change.</p>''')
 append(14,'''<h3>Published geography and internal strata serve different purposes</h3><p>In the 2023 Reference Paper, Chapter 4 describes 19 geographic strata: Quebec has three, Ontario four and British Columbia two, while the other provinces and three northern capital cities each have one. These are documented methodological strata, not a count inferred from the current public table. Intersecting product classes with geographic strata defines elementary aggregates. A public province-wide index can therefore summarize several internal geographic calculations, and a published selected-city series need not be a separate top-level national stratum.</p><p class="source">Reference Paper, paragraphs 4.3–4.4 and 4.8–4.9. The count is explicitly tied to the paper’s vintage; current public SDMX geography codes are displayed without treating them as a list of internal strata.</p>''')
 append(16,lab('A published rate in five visible steps','''<div class="controls"><label>Comparison <select id="official-walkthrough"><option value="yoy">Headline YoY</option><option value="mom">Headline unadjusted MoM</option><option value="sa">Headline adjusted MoM</option><option value="ontario">Ontario YoY</option></select></label></div><div id="official-walkthrough-steps" class="calculation-steps" aria-live="polite"></div>''','OFFICIAL OBSERVATIONS · INDEPENDENT ARITHMETIC'))
 append(18,'''<p class="source">The step cards can be selected directly or advanced with the single timeline. Synthetic examples are labelled in the explanation panel; Step 10 uses authentic September 2026 public observations.</p>''')

def refine_shell(html,asset):
 start=html.index('<div id="top" class="topline">');end=html.index('<div class="opening">',start)
 hero='''<header id="top" class="hero"><div class="hero-copy"><span class="eyebrow">AN INTERACTIVE RESEARCH MONOGRAPH</span><h1><span>Canada's Consumer Price Index:</span><em>From Everyday Prices to the Mathematics of Inflation</em></h1><p class="subtitle">From household purchases to elementary price indices, expenditure weights, seasonal adjustment and empirical replication with Statistics Canada data.</p></div><aside class="metadata" aria-label="Creation metadata"><div><span class="meta-icon" aria-hidden="true">📅</span><strong>Created:</strong><span>October 30, 2026</span></div><div><span class="meta-icon" aria-hidden="true">🧰</span><strong>Harness:</strong><span>Codex on Windows PowerShell</span></div><div><span class="meta-icon" aria-hidden="true">🖥️</span><strong>Model:</strong><span>GPT Sol-6.1</span></div><div><span class="meta-icon" aria-hidden="true">🧠</span><strong>Reasoning:</strong><span>High</span></div></aside></header>'''
 html=html[:start]+hero+html[end:]
 html=html.replace('<link rel="stylesheet" href="'+asset+'/styles.css">','<link rel="stylesheet" href="'+asset+'/styles.css"><link rel="stylesheet" href="'+asset+'/refinements.css">')
 html=html.replace('<script defer src="'+asset+'/app.js"></script>','<script defer src="'+asset+'/app.js"></script><script defer src="'+asset+'/data/processed/refinement-data.js"></script><script defer src="'+asset+'/refinements.js"></script>')
 html=html.replace('Green teaching panels', 'Peach teaching panels')
 attribution='<p class="source">Illustration provenance is recorded in the retained image manifest. Additional methodological references: <a href="https://www150.statcan.gc.ca/n1/pub/62-553-x/2023001/chap-5-eng.htm">Sample strategy and price collection</a>; <a href="https://www150.statcan.gc.ca/n1/pub/62-553-x/2023001/chap-6-eng.htm">Calculation of the CPI</a>; <a href="https://www.statcan.gc.ca/en/subjects-start/prices_and_price_indexes/consumer_price_indexes">CPI portal</a>; <a href="https://www150.statcan.gc.ca/n1/daily-quotidien/260615/dq260615c-eng.htm">2026 basket update</a>.</p>'
 html=html.replace('</footer>',attribution+'</footer>')
 return html
